mapper.select:
SELECT 

 WHERE ast06_company_id = #{companyId}
   AND ast06_date BETWEEN #{startDate} AND #{closeDate}
   AND ast06_tr_cd LIKE #{trCode}
   AND ast06_tr_cd IN ( SELECT ast15_tr_cd
                          FROM ast15_tr_code_window
                         WHERE ast15_company_id      = ast06_company_id
                           AND ast15_window_class_nm = 'Ast06_Tab_TrTax' )
 ORDER BY ast06_date desc, ast06_tr_id desc

mapper.update:
UPDATE ast06_tr
   SET ast06_appr_id = #{apprId}
 WHERE ast06_tr_id      = #{trId}
   AND ast06_company_id = #{companyId}
